window.kbPageData["views/entry/k-a65699576a82e6f0"] = {"key":"entry/k-a65699576a82e6f0","state":{"route":"entry/k-a65699576a82e6f0"},"node":{"id":"k-a65699576a82e6f0","mode":"k","title":"《美丽中国建设“十五五”规划》（7 月）","type":"事实与事件","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["生态环境"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《美丽中国建设“十五五”规划》（7 月）","slug":"435cb7099ccf"}],"directorySummary":"考点十九 《美丽中国建设“十五五”规划》（7 月）\n规划指出“十五五”时期是美丽中国建设承前启后、扩面提质，实现生态环境根本好转的关键\n阶段。践行绿水青山就是金山银山理念，以碳达峰碳中和为牵引，以健全生态文明制度体系为\n保障，统筹产业结构调整、污染治理、生态保护、应对气候变化，协同推进降碳、减污、扩…","sources":[{"id":"47ee3e64439de8e6","label":"《美丽中国建设“十五五”规划》（7 月）","topic":"重要文件","category":"时政","text":"考点十九 《美丽中国建设“十五五”规划》（7 月）\n规划指出“十五五”时期是美丽中国建设承前启后、扩面提质，实现生态环境根本好转的关键\n阶段。践行绿水青山就是金山银山理念，以碳达峰碳中和为牵引，以健全生态文明制度体系为\n保障，统筹产业结构调整、污染治理、生态保护、应对气候变化，协同推进降碳、减污、扩\n绿、增长，加快经济社会发展全面绿色转型，筑牢中华民族伟大复兴的生态根基。主要目标：\n到 2030 年，生态环境质量全面改善，美丽中国建设取得新的重大进展，碳达峰目标如期实\n现；到 2035 年，生态环境根本好转，美丽中国目标基本实现，全国 PM2.5 浓度下降到 25 微克\n/立方米以下，全经济范围温室气体净排放量比峰值下降 7%—10%，生态环境治理体系和治理\n能力现代化基本实现。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":16,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-a65699576a82e6f0":[]}};
